      "path": "packages/dsh-remote-web-ui/src/lan-forward.ts",
      "content": "/**\n * The LAN edge the lan-bind toggle owns (issue #1917).\n *\n * The toggle used to pin the LAN address into the profile's webserver row. That\n * row is the only place the harness takes its bind from, and rewriting it\n *   - replaced the official row's whole config (so the row's own\n *     `host: !!js ctx.webStartup.host ?? '127.0.0.1'` expression and the CLI\n *     `--host`/`--port` never reached it), and\n *   - the profile patch is watched by the Host's HMR config watcher, so the\n *     write recomposed the running process and rebound the live listener.\n *\n * This module keeps the host bound to loopback and gives LAN clients their own\n * listener: a forwarder on the machine's LAN address, on the same port, that\n * re-issues every request (HTTP and WebSocket upgrade alike) to\n * `127.0.0.1:<port>`. Two consequences are load-bearing:\n *\n * 1. The upstream leg is loopback, so the socket alone would read as \"the\n *    desktop\". The forwarder therefore DROPS whatever Host the client sent and\n *    stamps the LAN authority it was reached at, plus `X-Forwarded-For`. Every\n *    fence that decides \"is this the desktop\" (`isLoopbackClient`, the pairing\n *    gate, the `/remote` gate) then keeps refusing the forwarded request, while\n *    the phone-facing fences still match the LAN authority the QR advertises.\n * 2. A bind that cannot be taken (address gone after a network change, port\n *    taken) only loses the LAN edge: the loopback listener is never touched, so\n *    the host cannot be bricked and the failure is reported on the status\n *    frame.\n *\n * Nothing here writes a file: the forwarder is runtime state, so a network\n * change needs no profile edit and no restart.\n *\n * @module @linxin666/dsh-remote-web-ui/lan-forward\n */\n\nimport { createServer, request as httpRequest, type ClientRequest, type IncomingMessage, type Server, type ServerResponse } from 'node:http'\nimport { connect } from 'node:net'\nimport type { Duplex } from 'node:stream'\n\n/** The upstream the forwarder re-issues to: the process's own loopback listener. */\nexport const FORWARD_UPSTREAM_HOST = '127.0.0.1'\n\n/**\n * Headers that describe one hop rather than the request. They are rebuilt for\n * each leg so a keep-alive or upgrade marker from the client never leaks into\n * the loopback leg (and vice versa on the response).\n */\nconst HOP_BY_HOP = new Set([\n  'connection',\n  'keep-alive',\n  'proxy-authenticate',\n  'proxy-authorization',\n  'proxy-connection',\n  'te',\n  'trailer',\n  'transfer-encoding',\n  'upgrade',\n])\n\n/**\n * Headers the forwarder owns: a client-supplied value is discarded, never\n * appended to, so a LAN client cannot claim to be the desktop by forging them.\n */\nconst REWRITTEN = new Set(['host', 'x-forwarded-for', 'x-forwarded-proto', 'x-forwarded-host', 'cf-connecting-ip'])\n\n/** What the forwarder is doing right now, for the status frame and the logs. */\nexport interface LanForwardState {\n  /** Whether the LAN listener is bound. */\n  listening: boolean\n  /** The LAN address it listens on (undefined when it never bound). */\n  address: string | undefined\n  /** The port it listens on (the web server's own port). */\n  port: number | undefined\n  /** The loopback port it re-issues to. */\n  upstreamPort: number | undefined\n  /** Why the last bind attempt failed, when it did. */\n  error: string | undefined\n}\n\n/** The idle state: nothing bound, nothing failed. */\nexport const IDLE_FORWARD_STATE: LanForwardState = {\n  listening: false,\n  address: undefined,\n  port: undefined,\n  upstreamPort: undefined,\n  error: undefined,\n}\n\n/**\n * The `Host` authority a listener at `address:port` is reached at. IPv6\n * literals are bracketed like any URL authority.\n * @param address - the listen address (a literal).\n * @param port - the listen port.\n * @returns the authority text a request to that listener carries.\n */\nexport function authorityOf(address: string, port: number): string {\n  const host = address.includes(':') ? `[${address}]` : address\n  return `${host}:${String(port)}`\n}\n\n/**\n * The headers the loopback leg carries for one request: the client's own\n * headers minus the hop-by-hop and forwarder-owned ones, plus the LAN authority\n * the client actually reached and its address.\n * @param request - the request as it arrived on the LAN listener.\n * @param authority - the LAN authority the forwarder listens at.\n * @param clientAddress - the client's socket address, when readable.\n * @returns the headers for the loopback request.\n */\nexport function forwardedHeaders(\n  request: IncomingMessage,\n  authority: string,\n  clientAddress: string | undefined,\n): Record<string, string> {\n  const headers: Record<string, string> = {}\n  for (const [name, value] of Object.entries(request.headers)) {\n    if (value === undefined) continue\n    const lower = name.toLowerCase()\n    if (HOP_BY_HOP.has(lower) || REWRITTEN.has(lower)) continue\n    headers[lower] = Array.isArray(value) ? value.join(', ') : value\n  }\n  headers.host = authority\n  if (clientAddress !== undefined && clientAddress !== '') headers['x-forwarded-for'] = clientAddress\n  headers['x-forwarded-proto'] = 'http'\n  return headers\n}\n\n/**\n * Rebuild a WebSocket handshake for the loopback leg. The client's own headers\n * travel through verbatim (so `Sec-WebSocket-*` and any application protocol\n * survive) except the ones the forwarder owns.\n * @param request - the upgrade request as it arrived on the LAN listener.\n * @param authority - the LAN authority the forwarder listens at.\n * @param clientAddress - the client's socket address, when readable.\n * @returns the handshake request head to write on the loopback leg.\n */\nexport function forwardedHandshake(\n  request: IncomingMessage,\n  authority: string,\n  clientAddress: string | undefined,\n): string {\n  const lines = [`${request.method ?? 'GET'} ${request.url ?? '/'} HTTP/1.1`]\n  const raw = request.rawHeaders\n  for (let index = 0; index + 1 < raw.length; index += 2) {\n    const name = raw[index] ?? ''\n    const lower = name.toLowerCase()\n    if (REWRITTEN.has(lower)) continue\n    lines.push(`${name}: ${raw[index + 1] ?? ''}`)\n  }\n  lines.push(`Host: ${authority}`)\n  if (clientAddress !== undefined && clientAddress !== '') lines.push(`X-Forwarded-For: ${clientAddress}`)\n  lines.push('X-Forwarded-Proto: http')\n  return `${lines.join('\\r\\n')}\\r\\n\\r\\n`\n}\n\n/** One listener, its live connections, and its last bind outcome. */\nexport class LanForwarder {\n  private server: Server | undefined\n  private config: { address: string; port: number; upstreamPort: number } | undefined\n  private state: LanForwardState = IDLE_FORWARD_STATE\n  /** Every socket this forwarder opened on either leg. */\n  private readonly sockets = new Set<Duplex>()\n  /** Every in-flight loopback request, so a teardown cannot leave one running. */\n  private readonly upstreams = new Set<ClientRequest>()\n\n  /** What the forwarder is doing right now. */\n  snapshot(): LanForwardState {\n    return this.state\n  }\n\n  /**\n   * Bind the LAN listener, or report why it could not be bound.\n   *\n   * Never throws: a bind failure is the ordinary outcome after a network change\n   * (the address is gone) or a port collision, and the loopback listener must\n   * keep serving regardless.\n   * @param address - the LAN address to listen on.\n   * @param port - the port to listen on (the web server's own port).\n   * @param upstreamPort - the loopback port to re-issue to; defaults to `port`.\n   * @returns the settled state.\n   */\n  start(address: string, port: number, upstreamPort: number = port): Promise<LanForwardState> {\n    if (this.config !== undefined && this.state.listening\n      && this.config.address === address && this.config.port === port && this.config.upstreamPort === upstreamPort) {\n      return Promise.resolve(this.state)\n    }\n    return this.stop().then(() => this.bind(address, port, upstreamPort))\n  }\n\n  private bind(address: string, port: number, upstreamPort: number): Promise<LanForwardState> {\n    // The authority the requests are stamped with; re-read after listen so a\n    // kernel-assigned port (or a resolved address) is what clients are told.\n    let authority = authorityOf(address, port)\n    const server = createServer((request, response) => { this.forwardHttp(request, response, upstreamPort, authority) })\n    server.on('upgrade', (request, socket, head) => { this.forwardUpgrade(request, socket, head, upstreamPort, authority) })\n    server.on('connection', (socket) => {\n      this.sockets.add(socket)\n      socket.on('close', () => { this.sockets.delete(socket) })\n    })\n    this.server = server\n    this.config = { address, port, upstreamPort }\n    return new Promise<LanForwardState>((resolve) => {\n      let settled = false\n      const settle = (next: LanForwardState): void => {\n        if (settled) return\n        settled = true\n        this.state = next\n        resolve(next)\n      }\n      // A failed bind arrives as an 'error' event (EADDRINUSE, EADDRNOTAVAIL, a\n      // permission refusal). It is reported, never re-thrown: an unhandled\n      // 'error' on a listening server would take the whole host process down.\n      server.on('error', (error: NodeJS.ErrnoException) => {\n        const reason = error.code === undefined ? error.message : `${error.code}: ${error.message}`\n        if (this.server === server) {\n          this.server = undefined\n          this.config = undefined\n        }\n        this.releaseSockets()\n        settle({ listening: false, address, port, upstreamPort, error: reason })\n        if (!server.listening) return\n        server.close(() => undefined)\n      })\n      server.listen(port, address, () => {\n        // Report the address and port the kernel actually bound: a port of 0\n        // (and a wildcard-adjacent literal) is resolved by the listen call, and\n        // the status frame must name the listener clients can dial.\n        const bound = server.address()\n        const boundPort = typeof bound === 'object' && bound !== null ? bound.port : port\n        const boundAddress = typeof bound === 'object' && bound !== null ? bound.address : address\n        authority = authorityOf(boundAddress, boundPort)\n        this.config = { address: boundAddress, port: boundPort, upstreamPort }\n        settle({ listening: true, address: boundAddress, port: boundPort, upstreamPort, error: undefined })\n      })\n    })\n  }\n\n  /**\n   * Close the LAN listener and every connection it opened, then resolve once the\n   * port is released. Safe to call when nothing is bound.\n   */\n  stop(): Promise<void> {\n    const server = this.server\n    this.server = undefined\n    this.config = undefined\n    this.releaseSockets()\n    this.state = IDLE_FORWARD_STATE\n    if (server === undefined) return Promise.resolve()\n    return new Promise<void>((resolve) => {\n      server.close(() => { resolve() })\n      // Keep-alive and upgraded connections keep the handle alive; they are\n      // already destroyed above, so the close above settles on the next tick.\n      server.closeAllConnections?.()\n    })\n  }\n\n  private releaseSockets(): void {\n    for (const upstream of this.upstreams) upstream.destroy()\n    this.upstreams.clear()\n    for (const socket of this.sockets) socket.destroy()\n    this.sockets.clear()\n  }\n\n  private trackUpstream(upstream: ClientRequest): void {\n    this.upstreams.add(upstream)\n    upstream.on('close', () => { this.upstreams.delete(upstream) })\n  }\n\n  private forwardHttp(request: IncomingMessage, response: ServerResponse, upstreamPort: number, authority: string): void {\n    const upstream = httpRequest({\n      host: FORWARD_UPSTREAM_HOST,\n      port: upstreamPort,\n      method: request.method,\n      path: request.url,\n      headers: forwardedHeaders(request, authority, request.socket.remoteAddress),\n    }, (upstreamResponse) => {\n      const headers: Record<string, string | string[]> = {}\n      for (const [name, value] of Object.entries(upstreamResponse.headers)) {\n        if (value === undefined || HOP_BY_HOP.has(name.toLowerCase())) continue\n        headers[name] = value\n      }\n      response.writeHead(upstreamResponse.statusCode ?? 502, headers)\n      upstreamResponse.pipe(response)\n      upstreamResponse.on('error', () => { response.destroy() })\n      // The client left mid-response: stop the loopback leg instead of working\n      // on a call nobody will read.\n      response.on('close', () => {\n        if (!upstreamResponse.readableEnded) upstream.destroy()\n      })\n    })\n    this.trackUpstream(upstream)\n    upstream.on('error', () => {\n      if (response.headersSent) {\n        response.destroy()\n        return\n      }\n      response.writeHead(502, { 'content-type': 'text/plain; charset=utf-8' })\n      response.end('remote-web-ui: the LAN forwarder could not reach the loopback listener\\n')\n    })\n    request.on('error', () => { upstream.destroy() })\n    request.pipe(upstream)\n  }\n\n  private forwardUpgrade(request: IncomingMessage, socket: Duplex, head: Buffer, upstreamPort: number, authority: string): void {\n    const upstream = connect(upstreamPort, FORWARD_UPSTREAM_HOST)\n    this.sockets.add(upstream)\n    const tearDown = (): void => {\n      this.sockets.delete(upstream)\n      upstream.destroy()\n      socket.destroy()\n    }\n    upstream.on('error', tearDown)\n    socket.on('error', tearDown)\n    upstream.on('close', () => { socket.destroy() })\n    socket.on('close', () => { upstream.destroy() })\n    upstream.on('connect', () => {\n      upstream.write(forwardedHandshake(request, authority, request.socket.remoteAddress))\n      if (head.length > 0) upstream.write(head)\n      socket.pipe(upstream)\n      upstream.pipe(socket)\n    })\n  }\n}\n"
    },
    {
      "path": "packages/dsh-remote-web-ui/src/client/index.ts",
      "content": "/**\n * Remote control — browser half. Registers the `remote` dictionaries, the\n * sidebar-foot entry (phone trigger + pairing panel + update trigger), and\n * the pair boot flow (accept + presence heartbeats) plus the one-time\n * failed-pair notice. The portrait-touch adaptation of the official UI\n * starts under the plugin lifecycle (startMobileAdapt inside apply) and reverts\n * on dispose, so disabled plugin entries stay inert. Export discipline: packages/client/AGENTS.md — the\n * /client surface carries only what cordis loading needs plus types.\n */\nimport { createElement } from 'react'\nimport { createRoot } from 'react-dom/client'\nimport type { Context as ClientContext } from '@deepseek-ai/cordis'\nimport type { ConfigForm, ConfigForms } from '@deepseek-ai/dsh-client-ui-settings/client'\n// Type-only: pulls the locale plugin's Context merge (ctx.locale) and the\n// ui-sidebar SlotMap merge (the 'sidebar.footer.action' hole).\nimport type {} from '@deepseek-ai/dsh-client-locale/client'\n// Type-only: pulls the settings-surface SlotMap merge (the 'settings.section'\n// entry) and the ctx.configForms Context merge.\nimport type {} from '@deepseek-ai/dsh-client-ui-settings/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-sidebar/client'\n// Type-only: pulls the ctx.slots merge (the renderer owns the slot registry since 0.1.2).\nimport type {} from '@deepseek-ai/dsh-client-ui-renderer/client'\nimport type { ConnectionHandle } from '@deepseek-ai/dsh-client-connection/client'\nimport { FooterRemoteEntry } from './FooterRemoteEntry.tsx'\nimport { RemoteEntry } from './RemoteEntry.tsx'\nimport { PairFailedNotice } from './PairFailedNotice.tsx'\nimport { RemoteSettingsCard, RemoteSettingsCardController, type RemoteSettings } from './RemoteSettingsCard.tsx'\nimport { en, zh, type RemoteKey } from './locales.ts'\nimport { PAIR_FAILED_MARKER, runPairBootFlow } from './deep-link.ts'\nimport { readPairGatePolicy, sendHeartbeat, shouldStopHeartbeat } from './pair-api.ts'\nimport {\n  channelTransition,\n  installRemoteChannel,\n  pageOriginFacts,\n  remoteChannelRequired,\n  REMOTE_CHANNEL_BOOT_GLOBAL,\n  type RemoteChannelBootSeat,\n} from './remote-channel.ts'\nimport { isLocalPage } from '../remote-channel-rules.ts'\nimport { FenceNotice } from './FenceNotice.tsx'\nimport { reportDailyHeartbeat } from './telemetry.ts'\nimport { startMobileAdapt, type RemoteAdaptGlobal } from './mobile-adapt.ts'\nimport { installPluginCard } from './plugin-card-seat.ts'\nimport { createServedEntryForm } from './settings-entry-form.ts'\n\n// Portrait-touch adaptation of the official UI: installed under the plugin\n// lifecycle (apply) so disabling the plugin in cordis patch (disabled: true)\n// leaves the DOM untouched.\n\nexport type { RemoteEntryProps } from './RemoteEntry.tsx'\nexport type { PanelState, RemotePanelProps } from './RemotePanel.tsx'\nexport type { PairFailedNoticeProps } from './PairFailedNotice.tsx'\nexport type { RemoteKey } from './locales.ts'\nexport type { RemoteSettingsCardFace, RemoteSettingsCardState } from './RemoteSettingsCard.tsx'\n\ndeclare module '@deepseek-ai/dsh-client-ui-slots' {\n  interface LocaleNamespaceMap {\n    /** Mobile remote-control surface copy. */\n    remote: RemoteKey\n  }\n\n  interface SlotMap {\n    /**\n     * The sidebar foot seat beside the settings trigger, declared by the\n     * sidebar shell on deployments that carry the feature seat; the shell\n     * passes only its column display state.\n     */\n    /**\n     * The child slot the Web UI plugin group declares; this card registers\n     * into the group's list seat rather than the official\n     * bundle-configuration seat. Spelled here with the same shape so this\n     * package can register without depending on the sibling UI package.\n     */\n    'web-ui.plugin.item': { kind: 'list'; scope: 'root'; owner: SettingsPluginItemOwnerProps }\n  }\n}\n\n/** Owner share of the sidebar remote-control seat: the column display state the trigger renders against. */\nexport interface SidebarRemoteOwnerProps {\n  /** Whether the sidebar renders wide content (false = 56px rail). */\n  wide: boolean\n}\n\n/** Owner share of a plugin card (the section supplies nothing). */\nexport interface SettingsPluginItemOwnerProps {\n  /** Marker field: card owner props are intentionally empty. */\n  children?: never\n}\n\ndeclare module '@deepseek-ai/cordis' {\n  interface Context {\n    /**\n     * Optional family settings binder provided by dsh-web-settings; absent\n     * when that group plugin is not installed, so callers fall back to the\n     * official `ctx.configForms` service.\n     *\n     * The 0.1.7 client addresses one form per active profile entry id and\n     * carries no package identity, so the family binder resolves a family\n     * settings namespace to the entry that owns it and hands back that entry's\n     * shared form; the official service is addressed by the entry id directly.\n     */\n    webUiSettings?: {\n      bind<S>(spec: { namespace: string; decode?: (section: unknown) => S | undefined }): ConfigForm<S>\n    }\n  }\n}\n\n\n/** Dictionary namespace owned by this plugin. */\nconst NS = 'remote'\n\n/**\n * Settings namespace the remote-control card edits: the family identity of\n * this plugin's own settings form, and the row id a standalone bundle install\n * carries.\n */\nconst REMOTE_WEB_UI_NS = 'remote-web-ui'\n\n/** Profile entry id the family aggregate's generated row carries. */\nconst AGGREGATE_ENTRY_ID = 'web-ui-remote-web-ui'\n\n/** Profile entry ids this package's patch rows carry, most specific first. */\nconst REMOTE_WEB_UI_ENTRY_IDS: readonly string[] = [AGGREGATE_ENTRY_ID, 'ui-remote-web-ui', REMOTE_WEB_UI_NS]\n\n/**\n * The profile entry id this package's own row carries, for a page that serves\n * no family binder.\n *\n * The shared describe mirror answers asynchronously, so at plugin activation it\n * usually holds nothing yet — and an unanswered or empty mirror is not evidence\n * of absence. Binding the bare namespace there left the card bound to an entry\n * the Host does not serve, and the form is bound once per session, so the card\n * never recovered (every save answered `No configurable plugin entry`). The\n * aggregate row id matches nearly every deployment; only a mirror that answers\n * with OTHER plugins' rows falls back to the namespace itself (the pre-0.1.7\n * keying shape), because that answer is the one that actually proves this\n * package's own row is not served.\n * @param forms - the shared configuration forms service.\n * @returns the entry id to bind.\n */\nexport function servedEntryId(forms: ConfigForms): string {\n  let served: readonly string[] | undefined\n  try {\n    served = forms.describe().getSnapshot().view?.namespaces.map(view => view.ns)\n  } catch {\n    // A mirror that refuses the read is unanswered too, not absent.\n    served = undefined\n  }\n  if (served === undefined || served.length === 0) return AGGREGATE_ENTRY_ID\n  return REMOTE_WEB_UI_ENTRY_IDS.find(id => served.includes(id)) ?? REMOTE_WEB_UI_NS\n}\n\n/**\n * Bind the settings form the remote-control card reads and writes.\n *\n * The family binder comes first: it resolves this package's family namespace\n * onto the profile entry id the Host serves the form under, and keeps the\n * loopback bridge as its own fallback. A page without that group (or one where\n * its client half has not applied yet) binds through the shared forms service,\n * on the entry id the describe mirror justifies and rebound as soon as the\n * mirror answers — see {@link createServedEntryForm}.\n * @param ctx - client context carrying the family binder and/or the shared forms service.\n * @returns the form the card stages and saves through.\n */\nexport function bindSettingsForm(ctx: ClientContext): ConfigForm<RemoteSettings> {\n  const family = ctx.get('webUiSettings')\n  if (family !== undefined && typeof family.bind === 'function') {\n    return family.bind<RemoteSettings>({ namespace: REMOTE_WEB_UI_NS })\n  }\n  return createServedEntryForm<RemoteSettings>({\n    forms: ctx.configForms,\n    entryIds: REMOTE_WEB_UI_ENTRY_IDS,\n  })\n}\n\n/** Heartbeat cadence from a paired phone (presence + revocation liveness). */\nconst HEARTBEAT_INTERVAL_MS = 10_000\n\n/** Services required by this plugin. */\nexport const inject = ['slots', 'locale', 'connection', 'configForms', 'remote']\n\n/**\n * Register the remote-control surface.\n * @param ctx - client root context.\n */\nexport function apply(ctx: ClientContext): void {\n  // Portrait-touch adaptation of the official UI: installed under the plugin\n  // lifecycle so disabling the plugin in cordis patch (disabled: true) never\n  // injects mobile CSS, gesture hooks, or the whale floating button.\n  startMobileAdapt()\n  ctx.effect(() => () => {\n    ;(window as unknown as { __dshRemoteAdapt?: RemoteAdaptGlobal }).__dshRemoteAdapt?.setEnabled?.(false)\n  }, 'remote-web-ui: mobile-adapt')\n\n  // Anonymous install heartbeat (docs/telemetry.md): one beat per browser per\n  // UTC day, package name only, silent failure.\n  reportDailyHeartbeat([{ name: '@linxin666/dsh-remote-web-ui' }])\n\n  ctx.effect(() => {\n    try {\n      return ctx.locale.register(NS, { zh, en })\n    } catch {\n      return () => {}\n    }\n  }, 'remote-web-ui: dictionaries')\n\n  // The mobile adapt's whale button expands the collapsed sidebar and the\n  // activation closes the details panel — both through the official layout\n  // service (ctx.layout.toggleSidebar / closeDetails flip the panel state;\n  // the narrow-viewport semantics open the drawer).\n  const layout = ctx.get('layout') as { toggleSidebar?: () => void; closeDetails?: () => void } | undefined\n  const adapt = (window as unknown as { __dshRemoteAdapt?: RemoteAdaptGlobal }).__dshRemoteAdapt\n  // The official layout face throws (by contract) when the root entry has\n  // not mounted yet; these closures also fire from gestures racing that\n  // first mount, so they tolerate the throw instead of surfacing it.\n  const layoutCall = (call: (() => void) | undefined): void => {\n    try {\n      call?.()\n    } catch {\n      // Boot-order throw: the panel action is a no-op before the root entry.\n    }\n  }\n  if (layout !== undefined && adapt !== undefined) {\n    if (typeof layout.toggleSidebar === 'function') {\n      adapt.toggleSidebar = () => {\n        layoutCall(layout.toggleSidebar)\n      }\n    }\n    if (typeof layout.closeDetails === 'function') {\n      adapt.closeDetails = () => {\n        layoutCall(layout.closeDetails)\n      }\n    }\n  }\n  if (adapt !== undefined && adapt.toggleSidebar === null) {\n    // Layout face unavailable (older composition): fall back to clicking the\n    // official rail toggle when it exists.\n    adapt.toggleSidebar = () => {\n      (document.querySelector('[class$=\"_railFish\"] button, [class$=\"_logoRow\"] [class*=\"_iconButton\"]') as HTMLElement | null)?.click()\n    }\n  }\n\n  const t = ctx.locale.bind(NS)\n  // Hand the `remote` translate seat to the module-scope adaptation layer:\n  // the whale label was rendered with the English fallback before any\n  // dictionary existed; the wiring plus the layer's own sync tick re-renders\n  // it in the active locale.\n  if (adapt !== undefined) adapt.translate = t\n  // The settings form this card edits. The family group's binder resolves a\n  // family namespace to the profile entry that owns it and binds that entry's\n  // shared form (natively, or over its loopback bridge); without that group the\n  // namespace IS the owning entry id, so the official service is addressed\n  // directly.\n  const settingsForm: ConfigForm<RemoteSettings> = bindSettingsForm(ctx)\n  const enabled = (): boolean => {\n    const snapshot = settingsForm.getSnapshot()\n    return snapshot.status === 'ready'\n      ? snapshot.value?.enabled ?? true\n      : snapshot.status === 'unavailable'\n  }\n\n  // Master switch for the adaptation layer: the module-scope install runs\n  // before any config is readable, so flip it once the settings snapshot is\n  // bound and on every later change (disabled plugin = no injected surface).\n  // Also replay the pending closeDetails: the first portrait apply ran\n  // before the layout face was wired, so its closeDetails was a no-op and a\n  // restored details panel would otherwise sit hidden until landscape.\n  const syncAdaptEnabled = (): void => {\n    ;(window as unknown as { __dshRemoteAdapt?: RemoteAdaptGlobal }).__dshRemoteAdapt?.setEnabled?.(enabled())\n  }\n  settingsForm.subscribe(syncAdaptEnabled)\n  syncAdaptEnabled()\n  // The replay closes a details panel restored before the wiring; the\n  // layout face throws while the root entry has not mounted yet (a real\n  // boot-order race on slow remote loads), and the plugin's apply world\n  // must survive it — the replay is a best-effort no-op then.\n  try {\n    adapt?.flushCloseDetails?.()\n  } catch {}\n\n  // Sidebar foot entry: the sidebar foot seat is `sidebar.footer.action` in\n  // the 0.1.2 shell composition (the legacy `sidebar.remote` seat is gone\n  // upstream). The pairing link is origin-agnostic, so the entry needs no\n  // workspace source.\n  ctx.slots.inject('sidebar.footer.action', () => {\n    let disposeEntry: (() => void) | undefined\n    const syncEntry = (): void => {\n      if (enabled() && disposeEntry === undefined) {\n        try {\n          disposeEntry = ctx.slots.register({ name: 'sidebar.footer.action', id: 'remote-web-ui', locale: NS }, FooterRemoteEntry)\n        } catch {\n          // ignore registration collision\n        }\n      } else if (!enabled() && disposeEntry !== undefined) {\n        disposeEntry()\n        disposeEntry = undefined\n      }\n    }\n    const unsubscribe = settingsForm.subscribe(syncEntry)\n    syncEntry()\n    return () => {\n      unsubscribe()\n      disposeEntry?.()\n    }\n  })\n\n  // Plugin confi